INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES
  ('eeeeeeee-eeee-4eee-8eee-000000000001',NULL,'bbbbbbbb-bbbb-4bbb-8bbb-000000000003','heading_2','{"rich_text": [{"type": "text", "text": {"content": "Pending Handover Items"}}]}',0,0,1,'2026-05-19T10:40:00.000Z','2026-06-05T01:12:00.000Z'),
  ('eeeeeeee-eeee-4eee-8eee-000000000002',NULL,'bbbbbbbb-bbbb-4bbb-8bbb-000000000003','to_do','{"rich_text": [{"type": "text", "text": {"content": "Batch scheduling configuration and alert recipients (not done)"}}]}',0,0,2,'2026-05-19T10:40:00.000Z','2026-06-05T01:12:00.000Z'),
  ('eeeeeeee-eeee-4eee-8eee-000000000003',NULL,'bbbbbbbb-bbbb-4bbb-8bbb-000000000003','to_do','{"rich_text": [{"type": "text", "text": {"content": "Finance month-end close interface signing method; the existing doc is an outdated version (not done)"}}]}',0,0,3,'2026-05-19T10:40:00.000Z','2026-06-05T01:12:00.000Z'),
  ('eeeeeeee-eeee-4eee-8eee-000000000004',NULL,'bbbbbbbb-bbbb-4bbb-8bbb-000000000003','to_do','{"rich_text": [{"type": "text", "text": {"content": "Update the reconciliation exception handling SOP to the latest version (not done)"}}]}',0,0,4,'2026-05-19T10:40:00.000Z','2026-06-05T01:12:00.000Z'),
  ('eeeeeeee-eeee-4eee-8eee-000000000005',NULL,'bbbbbbbb-bbbb-4bbb-8bbb-000000000003','paragraph','{"rich_text": [{"type": "text", "text": {"content": "The permission checklist still has two systems to sort out: the settlement backend and the finance reconciliation console. Ask Li Zhe for admin access."}}]}',0,0,5,'2026-05-19T10:40:00.000Z','2026-06-05T01:12:00.000Z'),
  ('eeeeeeee-eeee-4eee-8eee-000000000006',NULL,'bbbbbbbb-bbbb-4bbb-8bbb-000000000004','heading_2','{"rich_text": [{"type": "text", "text": {"content": "Timeline"}}]}',0,0,1,'2025-11-02T02:15:00.000Z','2026-06-06T12:30:00.000Z'),
  ('eeeeeeee-eeee-4eee-8eee-000000000007',NULL,'bbbbbbbb-bbbb-4bbb-8bbb-000000000004','bulleted_list_item','{"rich_text": [{"type": "text", "text": {"content": "2018-08 joined, trading middle-office team, backend development"}}]}',0,0,2,'2025-11-02T02:15:00.000Z','2026-06-06T12:30:00.000Z'),
  ('eeeeeeee-eeee-4eee-8eee-000000000008',NULL,'bbbbbbbb-bbbb-4bbb-8bbb-000000000004','bulleted_list_item','{"rich_text": [{"type": "text", "text": {"content": "Since 2021, leading a 5-person team, responsible for accounting and reconciliation pipelines"}}]}',0,0,3,'2025-11-02T02:15:00.000Z','2026-06-06T12:30:00.000Z'),
  ('eeeeeeee-eeee-4eee-8eee-000000000009',NULL,'bbbbbbbb-bbbb-4bbb-8bbb-000000000004','bulleted_list_item','{"rich_text": [{"type": "text", "text": {"content": "2026-04 architecture review proposed module ownership adjustment"}}]}',0,0,4,'2025-11-02T02:15:00.000Z','2026-06-06T12:30:00.000Z'),
  ('eeeeeeee-eeee-4eee-8eee-000000000010',NULL,'bbbbbbbb-bbbb-4bbb-8bbb-000000000004','paragraph','{"rich_text": [{"type": "text", "text": {"content": "The base salary written in the contract differs a lot from the actual monthly take-home; the quarterly bonus and post allowance are paid separately. The exact figures need to be checked against the payroll card statement."}}]}',0,0,5,'2025-11-02T02:15:00.000Z','2026-06-06T12:30:00.000Z'),
  ('eeeeeeee-eeee-4eee-8eee-000000000011',NULL,'bbbbbbbb-bbbb-4bbb-8bbb-000000000005','heading_2','{"rich_text": [{"type": "text", "text": {"content": "Materials on Hand"}}]}',0,0,1,'2026-02-14T13:05:00.000Z','2026-06-07T14:40:00.000Z'),
  ('eeeeeeee-eeee-4eee-8eee-000000000012',NULL,'bbbbbbbb-bbbb-4bbb-8bbb-000000000005','bulleted_list_item','{"rich_text": [{"type": "text", "text": {"content": "Restricted stock incentive plan (company version, signed on paper)"}}]}',0,0,2,'2026-02-14T13:05:00.000Z','2026-06-07T14:40:00.000Z'),
  ('eeeeeeee-eeee-4eee-8eee-000000000013',NULL,'bbbbbbbb-bbbb-4bbb-8bbb-000000000005','bulleted_list_item','{"rich_text": [{"type": "text", "text": {"content": "Grant notification emails from past years, kept in personal email"}}]}',0,0,3,'2026-02-14T13:05:00.000Z','2026-06-07T14:40:00.000Z'),
  ('eeeeeeee-eeee-4eee-8eee-000000000014',NULL,'bbbbbbbb-bbbb-4bbb-8bbb-000000000005','bulleted_list_item','{"rich_text": [{"type": "text", "text": {"content": "Brokerage account opening documents"}}]}',0,0,4,'2026-02-14T13:05:00.000Z','2026-06-07T14:40:00.000Z'),
  ('eeeeeeee-eeee-4eee-8eee-000000000015',NULL,'bbbbbbbb-bbbb-4bbb-8bbb-000000000005','paragraph','{"rich_text": [{"type": "text", "text": {"content": "The buyback price clause in the plan text is written vaguely, only saying \"at the price the company determines at that time\". I did not read it closely back then."}}]}',0,0,5,'2026-02-14T13:05:00.000Z','2026-06-07T14:40:00.000Z'),
  ('eeeeeeee-eeee-4eee-8eee-000000000016',NULL,'bbbbbbbb-bbbb-4bbb-8bbb-000000000005','paragraph','{"rich_text": [{"type": "text", "text": {"content": "What needs to be clarified: whether the company can buy back the already-vested portion at its own set price."}}]}',0,0,6,'2026-02-14T13:05:00.000Z','2026-06-07T14:40:00.000Z'),
  ('eeeeeeee-eeee-4eee-8eee-000000000017',NULL,'bbbbbbbb-bbbb-4bbb-8bbb-000000000006','heading_2','{"rich_text": [{"type": "text", "text": {"content": "Fixed Schedule"}}]}',0,0,1,'2026-04-09T13:30:00.000Z','2026-06-04T11:50:00.000Z'),
  ('eeeeeeee-eeee-4eee-8eee-000000000018',NULL,'bbbbbbbb-bbbb-4bbb-8bbb-000000000006','paragraph','{"rich_text": [{"type": "text", "text": {"content": "Accompany prenatal checkups every Wednesday morning 09:00-11:30, until October. This time slot is non-negotiable; do not schedule anything."}}]}',0,0,2,'2026-04-09T13:30:00.000Z','2026-06-04T11:50:00.000Z'),
  ('eeeeeeee-eeee-4eee-8eee-000000000019',NULL,'bbbbbbbb-bbbb-4bbb-8bbb-000000000006','to_do','{"rich_text": [{"type": "text", "text": {"content": "The confinement nanny agency says the schedule must be finalized before end of June (not done)"}}]}',0,0,3,'2026-04-09T13:30:00.000Z','2026-06-04T11:50:00.000Z'),
  ('eeeeeeee-eeee-4eee-8eee-000000000020',NULL,'bbbbbbbb-bbbb-4bbb-8bbb-000000000006','to_do','{"rich_text": [{"type": "text", "text": {"content": "Stroller and car safety seat not yet bought (not done)"}}]}',0,0,4,'2026-04-09T13:30:00.000Z','2026-06-04T11:50:00.000Z'),
  ('eeeeeeee-eeee-4eee-8eee-000000000021',NULL,'bbbbbbbb-bbbb-4bbb-8bbb-000000000006','bulleted_list_item','{"rich_text": [{"type": "text", "text": {"content": "My mom buys the crib"}}]}',0,0,5,'2026-04-09T13:30:00.000Z','2026-06-04T11:50:00.000Z'),
  ('eeeeeeee-eeee-4eee-8eee-000000000022',NULL,'bbbbbbbb-bbbb-4bbb-8bbb-000000000007','heading_2','{"rich_text": [{"type": "text", "text": {"content": "Monthly Fixed Expenses"}}]}',0,0,1,'2026-03-08T07:20:00.000Z','2026-06-03T13:15:00.000Z'),
  ('eeeeeeee-eeee-4eee-8eee-000000000023',NULL,'bbbbbbbb-bbbb-4bbb-8bbb-000000000007','bulleted_list_item','{"rich_text": [{"type": "text", "text": {"content": "Rent 8500"}}]}',0,0,2,'2026-03-08T07:20:00.000Z','2026-06-03T13:15:00.000Z'),
  ('eeeeeeee-eeee-4eee-8eee-000000000024',NULL,'bbbbbbbb-bbbb-4bbb-8bbb-000000000007','bulleted_list_item','{"rich_text": [{"type": "text", "text": {"content": "Credit card repayment, variable"}}]}',0,0,3,'2026-03-08T07:20:00.000Z','2026-06-03T13:15:00.000Z'),
  ('eeeeeeee-eeee-4eee-8eee-000000000025',NULL,'bbbbbbbb-bbbb-4bbb-8bbb-000000000007','bulleted_list_item','{"rich_text": [{"type": "text", "text": {"content": "Utilities, telecom, fresh groceries, and commuting add up to roughly over three thousand"}}]}',0,0,4,'2026-03-08T07:20:00.000Z','2026-06-03T13:15:00.000Z'),
  ('eeeeeeee-eeee-4eee-8eee-000000000026',NULL,'bbbbbbbb-bbbb-4bbb-8bbb-000000000007','paragraph','{"rich_text": [{"type": "text", "text": {"content": "Expenses will rise after the child is born. Keep several months of buffer for the transition; do not sign casually just to get money quickly."}}]}',0,0,5,'2026-03-08T07:20:00.000Z','2026-06-03T13:15:00.000Z'),
  ('eeeeeeee-eeee-4eee-8eee-000000000027',NULL,'bbbbbbbb-bbbb-4bbb-8bbb-000000000008','heading_2','{"rich_text": [{"type": "text", "text": {"content": "Pitfalls Encountered"}}]}',0,0,1,'2026-04-26T06:33:00.000Z','2026-05-18T03:20:00.000Z'),
  ('eeeeeeee-eeee-4eee-8eee-000000000028',NULL,'bbbbbbbb-bbbb-4bbb-8bbb-000000000008','paragraph','{"rich_text": [{"type": "text", "text": {"content": "The reconciliation task originally ran for three hours, scanning the whole table. After adding partitioning by posted_at and reducing the batch size from fifty thousand to twenty thousand, it finishes in twenty-two minutes."}}]}',0,0,2,'2026-04-26T06:33:00.000Z','2026-05-18T03:20:00.000Z'),
  ('eeeeeeee-eeee-4eee-8eee-000000000029',NULL,'bbbbbbbb-bbbb-4bbb-8bbb-000000000008','paragraph','{"rich_text": [{"type": "text", "text": {"content": "Keep the gray-release switch; the rollback path must be verified once in advance, not just written in the docs."}}]}',0,0,3,'2026-04-26T06:33:00.000Z','2026-05-18T03:20:00.000Z'),
  ('eeeeeeee-eeee-4eee-8eee-000000000030',NULL,'bbbbbbbb-bbbb-4bbb-8bbb-000000000009','heading_2','{"rich_text": [{"type": "text", "text": {"content": "My Positioning"}}]}',0,0,1,'2026-05-24T14:10:00.000Z','2026-06-07T15:05:00.000Z'),
  ('eeeeeeee-eeee-4eee-8eee-000000000031',NULL,'bbbbbbbb-bbbb-4bbb-8bbb-000000000009','bulleted_list_item','{"rich_text": [{"type": "text", "text": {"content": "Direction: backend / platform, can write both Java and Go, distributed systems is the main line"}}]}',0,0,2,'2026-05-24T14:10:00.000Z','2026-06-07T15:05:00.000Z'),
  ('eeeeeeee-eeee-4eee-8eee-000000000032',NULL,'bbbbbbbb-bbbb-4bbb-8bbb-000000000009','bulleted_list_item','{"rich_text": [{"type": "text", "text": {"content": "City: Shanghai, wife is pregnant, not considering other cities"}}]}',0,0,3,'2026-05-24T14:10:00.000Z','2026-06-07T15:05:00.000Z'),
  ('eeeeeeee-eeee-4eee-8eee-000000000033',NULL,'bbbbbbbb-bbbb-4bbb-8bbb-000000000009','bulleted_list_item','{"rich_text": [{"type": "text", "text": {"content": "Preference: stable permanent positions, platform-type business"}}]}',0,0,4,'2026-05-24T14:10:00.000Z','2026-06-07T15:05:00.000Z'),
  ('eeeeeeee-eeee-4eee-8eee-000000000034',NULL,'bbbbbbbb-bbbb-4bbb-8bbb-000000000009','heading_2','{"rich_text": [{"type": "text", "text": {"content": "Red Lines"}}]}',0,0,5,'2026-05-24T14:10:00.000Z','2026-06-07T15:05:00.000Z'),
  ('eeeeeeee-eeee-4eee-8eee-000000000035',NULL,'bbbbbbbb-bbbb-4bbb-8bbb-000000000009','paragraph','{"rich_text": [{"type": "text", "text": {"content": "Outsourcing, labor dispatch, and on-site contracting roles - none of them, no matter how high the pay. Last time I was put in a passive position that way."}}]}',0,0,6,'2026-05-24T14:10:00.000Z','2026-06-07T15:05:00.000Z'),
  ('eeeeeeee-eeee-4eee-8eee-000000000036',NULL,'bbbbbbbb-bbbb-4bbb-8bbb-000000000010','to_do','{"rich_text": [{"type": "text", "text": {"content": "Add the quantified results of the database sharding wrap-up (not done)"}}]}',0,0,1,'2026-06-02T15:20:00.000Z','2026-06-07T13:40:00.000Z'),
  ('eeeeeeee-eeee-4eee-8eee-000000000037',NULL,'bbbbbbbb-bbbb-4bbb-8bbb-000000000010','to_do','{"rich_text": [{"type": "text", "text": {"content": "Highlight the reconciliation task reduction from three hours to twenty-two minutes (not done)"}}]}',0,0,2,'2026-06-02T15:20:00.000Z','2026-06-07T13:40:00.000Z'),
  ('eeeeeeee-eeee-4eee-8eee-000000000038',NULL,'bbbbbbbb-bbbb-4bbb-8bbb-000000000010','to_do','{"rich_text": [{"type": "text", "text": {"content": "Add the experience of leading a five-person team (not done)"}}]}',0,0,3,'2026-06-02T15:20:00.000Z','2026-06-07T13:40:00.000Z'),
  ('eeeeeeee-eeee-4eee-8eee-000000000039',NULL,'bbbbbbbb-bbbb-4bbb-8bbb-000000000010','paragraph','{"rich_text": [{"type": "text", "text": {"content": "When applying, do not mass-send one template; the JD highlights differ for each company."}}]}',0,0,4,'2026-06-02T15:20:00.000Z','2026-06-07T13:40:00.000Z'),
  ('eeeeeeee-eeee-4eee-8eee-000000000040',NULL,'bbbbbbbb-bbbb-4bbb-8bbb-000000000011','paragraph','{"rich_text": [{"type": "text", "text": {"content": "The chapters on local government investment and financing are worth re-reading. The relationship between fiscal revenue and land is the foundation for understanding many things."}}]}',0,0,1,'2025-12-19T05:43:00.000Z','2026-01-11T12:05:00.000Z'),
  ('eeeeeeee-eeee-4eee-8eee-000000000041',NULL,'bbbbbbbb-bbbb-4bbb-8bbb-000000000011','paragraph','{"rich_text": [{"type": "text", "text": {"content": "After reading, I recall my own hesitation when buying a house; back then I knew nothing about policy cycles."}}]}',0,0,2,'2025-12-19T05:43:00.000Z','2026-01-11T12:05:00.000Z'),
  ('eeeeeeee-eeee-4eee-8eee-000000000042',NULL,'bbbbbbbb-bbbb-4bbb-8bbb-000000000012','paragraph','{"rich_text": [{"type": "text", "text": {"content": "The three concepts of stock, flow, and feedback loops explain the causes of many production incidents."}}]}',0,0,1,'2025-10-06T15:23:00.000Z','2025-10-27T09:07:00.000Z'),
  ('eeeeeeee-eeee-4eee-8eee-000000000043',NULL,'bbbbbbbb-bbbb-4bbb-8bbb-000000000012','paragraph','{"rich_text": [{"type": "text", "text": {"content": "Delayed feedback makes people over-adjust - this is especially evident in capacity planning."}}]}',0,0,2,'2025-10-06T15:23:00.000Z','2025-10-27T09:07:00.000Z'),
  ('eeeeeeee-eeee-4eee-8eee-000000000044',NULL,'bbbbbbbb-bbbb-4bbb-8bbb-000000000013','heading_2','{"rich_text": [{"type": "text", "text": {"content": "Checkups and Routine"}}]}',0,0,1,'2026-01-04T04:27:00.000Z','2026-05-30T00:45:00.000Z'),
  ('eeeeeeee-eeee-4eee-8eee-000000000045',NULL,'bbbbbbbb-bbbb-4bbb-8bbb-000000000013','bulleted_list_item','{"rich_text": [{"type": "text", "text": {"content": "2026-01 checkup: uric acid slightly high, otherwise normal"}}]}',0,0,2,'2026-01-04T04:27:00.000Z','2026-05-30T00:45:00.000Z'),
  ('eeeeeeee-eeee-4eee-8eee-000000000046',NULL,'bbbbbbbb-bbbb-4bbb-8bbb-000000000013','bulleted_list_item','{"rich_text": [{"type": "text", "text": {"content": "Doctor advised drinking fewer sugary beverages and cutting back on late-night snacks"}}]}',0,0,3,'2026-01-04T04:27:00.000Z','2026-05-30T00:45:00.000Z'),
  ('eeeeeeee-eeee-4eee-8eee-000000000047',NULL,'bbbbbbbb-bbbb-4bbb-8bbb-000000000013','paragraph','{"rich_text": [{"type": "text", "text": {"content": "April and May were busy with the project, lots of late nights, recently constant headaches. Once this period passes, need to get back on track."}}]}',0,0,4,'2026-01-04T04:27:00.000Z','2026-05-30T00:45:00.000Z'),
  ('eeeeeeee-eeee-4eee-8eee-000000000048',NULL,'bbbbbbbb-bbbb-4bbb-8bbb-000000000014','paragraph','{"rich_text": [{"type": "text", "text": {"content": "Originally planned a trip to Yunnan this autumn, but put it aside after my wife got pregnant."}}]}',0,0,1,'2025-12-27T06:22:00.000Z','2026-04-05T03:09:00.000Z'),
  ('eeeeeeee-eeee-4eee-8eee-000000000049',NULL,'bbbbbbbb-bbbb-4bbb-8bbb-000000000014','paragraph','{"rich_text": [{"type": "text", "text": {"content": "Wait until the child is a bit older; flights and hotels are not booked."}}]}',0,0,2,'2025-12-27T06:22:00.000Z','2026-04-05T03:09:00.000Z'),
  ('eeeeeeee-eeee-4eee-8eee-000000000050',NULL,'bbbbbbbb-bbbb-4bbb-8bbb-000000000015','heading_2','{"rich_text": [{"type": "text", "text": {"content": "Things to Catch Up On This Year"}}]}',0,0,1,'2026-01-18T01:40:00.000Z','2026-05-12T12:30:00.000Z'),
  ('eeeeeeee-eeee-4eee-8eee-000000000051',NULL,'bbbbbbbb-bbbb-4bbb-8bbb-000000000015','bulleted_list_item','{"rich_text": [{"type": "text", "text": {"content": "Several implementation approaches for distributed transactions, compare them side by side"}}]}',0,0,2,'2026-01-18T01:40:00.000Z','2026-05-12T12:30:00.000Z'),
  ('eeeeeeee-eeee-4eee-8eee-000000000052',NULL,'bbbbbbbb-bbbb-4bbb-8bbb-000000000015','bulleted_list_item','{"rich_text": [{"type": "text", "text": {"content": "That Geek Time course, 62% progress"}}]}',0,0,3,'2026-01-18T01:40:00.000Z','2026-05-12T12:30:00.000Z'),
  ('eeeeeeee-eeee-4eee-8eee-000000000053',NULL,'bbbbbbbb-bbbb-4bbb-8bbb-000000000015','to_do','{"rich_text": [{"type": "text", "text": {"content": "Understand the hanging problem in Seata AT mode (not done)"}}]}',0,0,4,'2026-01-18T01:40:00.000Z','2026-05-12T12:30:00.000Z'),
  ('eeeeeeee-eeee-4eee-8eee-000000000054',NULL,'bbbbbbbb-bbbb-4bbb-8bbb-000000000016','paragraph','{"rich_text": [{"type": "text", "text": {"content": "The lease expires at the end of August; the landlord mentioned raising the rent."}}]}',0,0,1,'2026-03-15T08:50:00.000Z','2026-03-22T02:12:00.000Z'),
  ('eeeeeeee-eeee-4eee-8eee-000000000055',NULL,'bbbbbbbb-bbbb-4bbb-8bbb-000000000016','paragraph','{"rich_text": [{"type": "text", "text": {"content": "If really moving, commute and distance to the hospital are two hard constraints."}}]}',0,0,2,'2026-03-15T08:50:00.000Z','2026-03-22T02:12:00.000Z');
